import json
import subprocess
import sys

def run_pipeline(req, execute=False):
    args = [sys.executable, 'etl_pipeline.py']
    if execute:
        args.append('--execute')
    result = subprocess.run(
        args,
        input=json.dumps(req),
        text=True,
        capture_output=True
    )
    return json.loads(result.stdout)

print("Testing backward compatibility with existing operations:")

# Test select
test = {
    "pipeline": {"steps": [
        {"op": "select", "columns": ["id", "name"]}
    ]},
    "dataset": [{"id": 1, "name": "Alice", "age": 30}]
}
resp = run_pipeline(test, execute=True)
print("  Select:", "PASS" if resp['status'] == 'ok' and resp['metrics']['rows_in'] == 1 and resp['metrics']['rows_out'] == 1 else f"FAIL: {resp}")

# Test filter
test = {
    "pipeline": {"steps": [
        {"op": "filter", "where": "x > 5"}
    ]},
    "dataset": [{"x": 3}, {"x": 10}]
}
resp = run_pipeline(test, execute=True)
print("  Filter:", "PASS" if resp['status'] == 'ok' and resp['metrics']['rows_out'] == 1 else f"FAIL: {resp}")

# Test map
test = {
    "pipeline": {"steps": [
        {"op": "map", "as": "double", "expr": "x * 2"}
    ]},
    "dataset": [{"x": 5}]
}
resp = run_pipeline(test, execute=True)
print("  Map:", "PASS" if resp['status'] == 'ok' and resp['data'][0]['double'] == 10 else f"FAIL: {resp}")

# Test rename (from/to form)
test = {
    "pipeline": {"steps": [
        {"op": "rename", "from": "old_name", "to": "new_name"}
    ]},
    "dataset": [{"old_name": "value"}]
}
resp = run_pipeline(test, execute=True)
print("  Rename (from/to):", "PASS" if resp['status'] == 'ok' and "new_name" in resp['data'][0] else f"FAIL: {resp}")

# Test rename (mapping form)
test = {
    "pipeline": {"steps": [
        {"op": "rename", "mapping": {"a": "x", "b": "y"}}
    ]},
    "dataset": [{"a": 1, "b": 2}]
}
resp = run_pipeline(test, execute=True)
print("  Rename (mapping):", "PASS" if resp['status'] == 'ok' and "x" in resp['data'][0] and "y" in resp['data'][0] else f"FAIL: {resp}")

# Test limit
test = {
    "pipeline": {"steps": [
        {"op": "limit", "n": 1}
    ]},
    "dataset": [{"x": 1}, {"x": 2}, {"x": 3}]
}
resp = run_pipeline(test, execute=True)
print("  Limit:", "PASS" if resp['status'] == 'ok' and resp['metrics']['rows_out'] == 1 else f"FAIL: {resp}")

# Test branch
test = {
    "pipeline": {"steps": [
        {"op": "branch", "branches": [
            {"when": "x > 5", "steps": [
                {"op": "map", "as": "category", "expr": "'big'"}
            ]},
            {"when": "otherwise", "steps": [
                {"op": "map", "as": "category", "expr": "'small'"}
            ]}
        ]}
    ]},
    "dataset": [{"x": 10}, {"x": 2}]
}
resp = run_pipeline(test, execute=True)
print("  Branch:", "PASS" if resp['status'] == 'ok' and resp['metrics']['rows_out'] == 2 and all('category' in r for r in resp['data']) else f"FAIL: {resp}")

# Test complex pipeline with multiple steps
test = {
    "pipeline": {"steps": [
        {"op": "select", "columns": ["id", "score"]},
        {"op": "filter", "where": "score >= 50"},
        {"op": "map", "as": "pass", "expr": "score >= 60"},
        {"op": "limit", "n": 10}
    ]},
    "dataset": [
        {"id": 1, "score": 45},
        {"id": 2, "score": 65},
        {"id": 3, "score": 75}
    ]
}
resp = run_pipeline(test, execute=True)
print("  Complex pipeline:", "PASS" if resp['status'] == 'ok' and resp['metrics']['rows_out'] == 2 else f"FAIL: {resp}")

# Test normalize-only mode (no execute)
test = {
    "pipeline": {"steps": [
        {"op": "select", "columns": ["id"]}
    ]},
    "dataset": []
}
resp = run_pipeline(test, execute=False)
print("  Normalize mode:", "PASS" if resp['status'] == 'ok' and 'normalized' in resp else f"FAIL: {resp}")

print("\nAll backward compatibility tests completed!")
